"""The steps themselves. Each takes text and returns text."""


class Step:
    """One transformation."""

    def apply(self, text: str) -> str:
        raise NotImplementedError


class Upper(Step):
    def apply(self, text: str) -> str:
        return text.upper()


class Strip(Step):
    def apply(self, text: str) -> str:
        return text.strip()


class Squeeze(Step):
    def apply(self, text: str) -> str:
        return " ".join(text.split())


class Truncate(Step):
    def __init__(self, length: int = 0):
        self.length = length

    def apply(self, text: str) -> str:
        return text[: self.length]

"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        prefix, _, arg = name.partition(":")
        if prefix not in STEPS:
            raise KeyError(f"no step named {prefix!r}. Known: {', '.join(sorted(STEPS))}")
        step_cls = type(STEPS[prefix])
        if step_cls is Truncate:
            if not arg:
                raise ValueError(f"truncate requires a length argument (got {name!r})")
            try:
                length = int(arg)
            except ValueError:
                raise ValueError(
                    f"truncate length must be an integer (got {arg!r} in {name!r})"
                )
            return Truncate(length)
        # steps without args that happen to have a colon are not supported
        raise KeyError(f"no step named {prefix!r}. Known: {', '.join(sorted(STEPS))}")
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

import pytest
from pipeline.runner import run_pipeline


def test_upper():
    assert run_pipeline("abc", ["upper"]) == "ABC"


def test_chain():
    assert run_pipeline("  a   b  ", ["strip", "squeeze"]) == "a b"


def test_unknown_step():
    with pytest.raises(KeyError):
        run_pipeline("x", ["nope"])


# --- truncate tests ---


def test_truncate_basic():
    assert run_pipeline("abcdef", ["truncate:3"]) == "abc"


def test_truncate_past_end():
    assert run_pipeline("abc", ["truncate:99"]) == "abc"


def test_truncate_zero():
    assert run_pipeline("abc", ["truncate:0"]) == ""


def test_truncate_missing_length():
    with pytest.raises(ValueError):
        run_pipeline("abc", ["truncate:"])


def test_truncate_non_numeric():
    with pytest.raises(ValueError):
        run_pipeline("abc", ["truncate:abc"])


def test_truncate_bare_name():
    with pytest.raises(ValueError):
        run_pipeline("abc", ["truncate"])


def test_strip_then_truncate():
    assert run_pipeline("  hello world  ", ["strip", "truncate:5"]) == "hello"


def test_upper_still_works():
    assert run_pipeline("abc", ["upper"]) == "ABC"


def test_strip_still_works():
    assert run_pipeline("  x  ", ["strip"]) == "x"


def test_squeeze_still_works():
    assert run_pipeline("a  b", ["squeeze"]) == "a b"

